const media = await figma.getNodeByIdAsync('1:254');
const page0 = await figma.getNodeByIdAsync('1:3');
await figma.setCurrentPageAsync(page);
const old = page.findOne(n=>n.name==='11_Your_Journey'); if (old) old.remove();
const Q=(s)=>figma.loadFontAsync({family:'Quicksand',style:s});
const N=(s)=>figma.loadFontAsync({family:'Nunito',style:s});
await Q('Bold'); await Q('Semi Bold'); await N('Regular'); await N('Bold'); await N('Semi Bold');
const INK={r:.169,g:.227,b:.2},MUT={r:.361,g:.42,b:.388},SUB={r:.576,g:.651,b:.612},DEEP={r:.373,g:.69,b:.533},BG={r:.957,g:.973,b:.961},W={r:1,g:1,b:1},TINT={r:.918,g:.961,b:.937},LINE={r:.878,g:.914,b:.89},AMBER={r:.788,g:.541,b:.176},AMBERT={r:.988,g:.953,b:.886},BLUE={r:.286,g:.541,b:.831},BLUET={r:.906,g:.937,b:.973};
function inst(name){ const s=media.findOne(n=>n.name===name && n.type==='SYMBOL'); if(!s) throw new Error('no symbol '+name); return s.createInstance(); }
const i=(n,s)=>{const x=inst(n); x.resize(s,s); return x;};
function txt(ch,fn,sz,c,w){ const t=figma.createText(); t.fontName=fn; t.characters=ch; t.fontSize=sz; t.fills=[{type:'SOLID',color:c}]; if(w){t.textAutoResize='HEIGHT_AND_WIDTH'; t.resize(w,1);} return t; }
function card(w,h,fc){ const c=figma.createFrame(); c.resize(w,h); c.fills=[{type:'SOLID',color:fc||W}]; c.cornerRadius=20; return c; }

const f=figma.createFrame(); f.name='11_Your_Journey'; f.resize(390,844); f.x=3440; f.y=0;
f.fills=[{type:'SOLID',color:BG}]; f.clipsContent=true; page.appendChild(f);

const sbRef=page0.findOne(n=>n.type==='COMPONENT' && n.name==='Status Bar');
const hiRef=page0.findOne(n=>n.type==='COMPONENT' && n.name==='Home Indicator');
const sb=sbRef.createInstance(); f.appendChild(sb); sb.x=0; sb.y=0;

const av=inst('Avatar_Alex'); f.appendChild(av); av.x=16; av.y=64; av.resize(56,56);
const h1=txt('Your Journey',{family:'Quicksand',style:'Bold'},24,INK); f.appendChild(h1); h1.x=84; h1.y=68;
const sub=txt('Reflect on your emotional trends',{family:'Nunito',style:'Regular'},15,MUT); f.appendChild(sub); sub.x=84; sub.y=98;

const filters=[['All Entries',true],['Journal',false],['Highlights',false]];
let fx=16; for (const [lb,cur] of filters){
  const w2=lb.length*8+28;
  const chp=figma.createFrame(); chp.resize(w2,36); chp.cornerRadius=18;
  chp.fills=[{type:'SOLID',color:cur?DEEP:W}];
  if(!cur){ chp.strokes=[{type:'SOLID',color:LINE}]; chp.strokeWeight=1; }
  f.appendChild(chp); chp.x=fx; chp.y=138; chp.name='Filter · '+lb;
  const t=txt(lb,{family:'Nunito',style:cur?'Bold':'Semi Bold'},14,cur?W:MUT); f.appendChild(t); t.x=fx+14; t.y=138+18-t.height/2;
  fx+=w2+10;
}

const oc=card(358,186,W); f.appendChild(oc); oc.x=16; oc.y=194; oc.name='October Overview';
const oic=figma.createFrame(); oic.resize(40,40); oic.cornerRadius=12; oic.fills=[{type:'SOLID',color:TINT}]; f.appendChild(oic); oic.x=34; oic.y=212;
const cal=i('Icon_Calendar',20); f.appendChild(cal); cal.x=44; cal.y=222;
const ot=txt('October Overview',{family:'Quicksand',style:'Bold'},17,INK); f.appendChild(ot); ot.x=84; ot.y=215;
const os=txt('You’ve been mostly Calm this month.',{family:'Nunito',style:'Regular'},13,MUT,240); f.appendChild(os); os.x=84; os.y=240;
const bars=[{v:.5,c:BLUET},{v:.35,c:BLUET},{v:.9,c:DEEP},{v:.55,c:BLUET},{v:.4,c:BLUET},{v:.8,c:DEEP},{v:.95,c:DEEP}];
bars.forEach((b,ix)=>{
  const r=figma.createRectangle(); const bh=64*b.v;
  r.resize(26,bh); r.cornerRadius=8; r.fills=[{type:'SOLID',color:b.c}];
  f.appendChild(r); r.x=34+ix*44; r.y=352-bh;
});

const groups=[
 {day:'TODAY', entries:[
   {time:'8 PM',title:'Evening Reflection',tag:null,note:'Feeling peaceful after the study session. The meditation really helped…',calm:true},
   {time:'2 PM',title:'Pre-Exam Jitters',tag:'Deadline',note:'Heart beating a bit fast thinking about the Chemistry final.',calm:false},
 ]},
 {day:'YESTERDAY', entries:[
   {time:'9 AM',title:'Rough Start',tag:'Exam Week',note:'Overslept and missed the bus. Feeling overwhelmed immediately.',calm:false},
   {time:'1 PM',title:'Lunch w/ Sarah',tag:null,note:'Talking it out helped so much. Feeling supported.',calm:true},
 ]},
 {day:'TUESDAY, OCT 24', entries:[
   {time:'4 PM',title:'Library Grind',tag:null,note:'Just focused. Not happy, not sad. Just doing the work.',calm:true},
 ]},
];
let y=404;
const rail=figma.createRectangle(); rail.resize(2,690); rail.fills=[{type:'SOLID',color:LINE}]; f.appendChild(rail); rail.x=25; rail.y=404;

for (const g of groups){
  const d=txt(g.day,{family:'Nunito',style:'Bold'},12,SUB); d.letterSpacing={unit:'PERCENT',value:8}; f.appendChild(d); d.x=44; d.y=y;
  y+=30;
  for (const e of g.entries){
    const dot=figma.createEllipse(); dot.resize(12,12); dot.fills=[{type:'SOLID',color:e.calm?DEEP:AMBER}]; dot.strokes=[{type:'SOLID',color:BG}]; dot.strokeWeight=3; f.appendChild(dot); dot.x=20; dot.y=y+2;
    const c2=card(316,96,W); f.appendChild(c2); c2.x=44; c2.y=y; c2.name='Entry · '+e.title;
    const tt=txt(e.time,{family:'Nunito',style:'Bold'},12,SUB); f.appendChild(tt); tt.x=60; tt.y=y+14;
    const ti=txt(e.title,{family:'Quicksand',style:'Bold'},15,INK); f.appendChild(ti); ti.x=60; ti.y=y+32;
    if (e.tag){
      const tw=e.tag.length*7+20;
      const tg=figma.createFrame(); tg.resize(tw,24); tg.cornerRadius=12; tg.fills=[{type:'SOLID',color:AMBERT}]; f.appendChild(tg); tg.x=344-tw; tg.y=y+14;
      const ttx=txt(e.tag,{family:'Nunito',style:'Bold'},11,AMBER); f.appendChild(ttx); ttx.x=344-tw+10; ttx.y=y+14+12-ttx.height/2;
    }
    const nt=txt(e.note,{family:'Nunito',style:'Regular'},13,MUT,284); f.appendChild(nt); nt.x=60; nt.y=y+54;
    y+=108;
  }
  y+=12;
}

const hint=txt('Keep tracking to see more patterns',{family:'Nunito',style:'Semi Bold'},13,SUB); f.appendChild(hint); hint.x=195-hint.width/2; hint.y=750;
const fab=figma.createFrame(); fab.name='Add Entry'; fab.resize(56,56); fab.cornerRadius=28; fab.fills=[{type:'SOLID',color:DEEP}];
fab.effects=[{type:'DROP_SHADOW',color:{r:.18,g:.33,b:.24,a:.35},offset:{x:0,y:6},radius:14,spread:0,visible:true,blendMode:'NORMAL'}];
f.appendChild(fab); fab.x=318; fab.y=686;
const plus=txt('+',{family:'Nunito',style:'Bold'},30,W); f.appendChild(plus); plus.x=318+28-plus.width/2; plus.y=686+28-plus.height/2;

const hi=hiRef.createInstance(); f.appendChild(hi); hi.x=0; hi.y=810;
return {id:f.id, bottomY:y};

